Rails.application.routes.draw do
  # The Assignment 1 landing page is the home of the application
  root "pages#home"

  # Accounts: sign in and out, password reset by email (generated by
  # `bin/rails generate authentication`), sign up and the member's own profile
  resource :session
  resources :passwords, param: :token
  get  "sign_up", to: "registrations#new"
  post "sign_up", to: "registrations#create"
  resource :profile, only: %i[show edit update]

  # Development only: the emails the app sends, at /letter_opener
  mount LetterOpenerWeb::Engine, at: "/letter_opener" if Rails.env.development? && defined?(LetterOpenerWeb)

  # Catalogs
  resources :neighborhoods
  resources :amenities, except: :show

  # A listing is always created inside a property, and reviews are written from the property page
  resources :properties do
    resources :listings, only: %i[new create]
    resources :reviews,  only: :create
  end

  # Seekers apply from the listing page
  # The host moves a listing through its lifecycle from the listing page
  resources :listings, only: %i[index show edit update destroy] do
    member do
      patch :publish
      patch :withdraw
      patch :mark_rented
    end
    resources :applications, only: :create
    resources :reports, only: :create
  end

  # Moderators review the reports about listings: dismiss them, or uphold them (the room is withdrawn)
  resources :reports, only: :index do
    member do
      patch :dismiss
      patch :uphold
    end
  end

  # Hosts propose visits on an application
  # The seeker withdraws; the host shortlists, rejects or accepts
  resources :applications, only: %i[index show] do
    member do
      patch :withdraw
      patch :shortlist
      patch :reject
      patch :accept
    end
    resources :visits, only: :create
  end

  # edit/update reschedule a visit: the old one is cancelled and a new one is proposed
  resources :visits, only: %i[edit update] do
    member do
      patch :confirm
      patch :cancel
      patch :complete
    end
  end

  resources :reviews, only: %i[edit update destroy]

  # Public JSON API: published listings and the catalogs to filter them, without personal data
  namespace :api, defaults: { format: :json } do
    namespace :v1 do
      resources :listings, only: %i[index show]
      resources :neighborhoods, only: :index
      resources :amenities, only: :index
    end
  end

  # Reveal health status on /up that returns 200 if the app boots with no exceptions, otherwise 500.
  # Can be used by load balancers and uptime monitors to verify that the app is live.
  get "up" => "rails/health#show", as: :rails_health_check
end
